// Rule L9 from a graph: a Function of this file returns its first `out` once migrated, so a statement call that passes
// it assigns it, a value call reads it, and a selection takes it from the call's own variable.
/// @custom
float MrRemap(float value, out float spare)
{
    float result = (float)0;
    result = saturate(value * 0.5 + 0.5);
    spare = value;
    return result;
}

/// @custom
float MrTwice(float value)
{
    float result = (float)0;
    float r;
    float s;
    r = MrRemap(value, s);
    result = r * 2.0;
    return result;
}

/// @name DreamShaderTests/Migrate/M_MrReturnsFirstOut
export void M_MrReturnsFirstOut(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float First = 0;
    float Spare = 0;
    First = MrRemap(0.25, Spare);
    float Second = MrTwice(First);
    float MrRemap_spare;
    float MrRemap_result = MrRemap(0.75, spare = MrRemap_spare);
    Color = float3(First, Second, MrRemap_spare);
    Alpha = Spare;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
